  liveEnabled && !batchRunning
   ? {
      id: -1,
      kind: "live audit",
      target: "proxied traffic",
      state: "running",
      done: 0,
      total: 0,
      fraction: 0,
      fraction_known: false,
      cancellable: true,
      progress: "waiting for in-scope traffic",
      elapsed_ms: 0,
      result: { summary: "" },
