    <Input aria-label="Filter tasks" placeholder="Filter tasks" value={filter} onChange={(event) => setFilter(event.target.value)} />
    <Search size={13} className="task-sidebar-filter-icon" />
   </div>
   {shown.length ? (
    <div className="task-tile-list">
