       selected={selectedId === task.id}
       onSelect={() => onSelect(task.id)}
       liveFindings={liveFindings}
       liveEnabled={liveEnabled}
      />
     ))}
    </div>
   ) : (
    <Empty
     title={needle ? "No matching tasks" : "No tasks"}
