    target = '#rows';
  } else if (what === 'organizer') {
    url = '/ui2/organizer';
    target = '#rows';
  } else if (what === 'proxy') {
    url = '/ui2/proxy';
    target = '#rows';
  } else if (what === 'dashboard') {
    url = '/ui2/dashboard';
    target = '#rows';
  } else if (what === 'session') {
    url = '/ui2/session';
    target = '#rows';
  } else if (what === 'scope') {
    url = '/ui2/scope';
    target = '#srows';
  } else if (what === 'sequencer') {
    url = '/ui2/sequencer';
    target = '#rows';
  } else { return; }
